package org.eclipse.jdt.internal.ui.callhierarchy;

public class CallHierarchyUI {
    // Minimal definitions to make the example self-contained and compilable
    static class IJavaElement {}
    static class CallLocation {
        public IJavaElement getCalledMember() { return null; }
        public IJavaElement getMember() { return null; }
    }
    static class MethodWrapper {
        public IJavaElement getMember() { return null; }
    }
    static class EditorUtility {
        public static boolean isOpenInEditor(IJavaElement element) { return true; }
    }

    public boolean revealElementInEditor(Object elem) {
        IJavaElement javaElement = null;
        if (elem instanceof MethodWrapper) {
            javaElement = ((MethodWrapper) elem).getMember();
        } else if (elem instanceof CallLocation) {
            // The target line for the cleanup
            javaElement = ((CallLocation) elem).getCalledMember();
        }
        if (javaElement != null) {
            return EditorUtility.isOpenInEditor(javaElement);
        }
        return false;
    }
}

